import Style1 from './teacher.module.css';
import Teachernav from './teachernav';
import React, { useState } from "react";



function Addresult() {
 const [result, setResult] = useState({
    examType: "",
    roll: "",
    class: "",
    telugu: "",
    hindi: "",
    english: "",
    maths: "",
    science: "",
    social: "",
  });

  // Handle input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setResult({ ...result, [name]: value });
  };

  // Handle form submission
  const handleSubmit = async () => {
    if (
      !result.examType ||
      !result.roll ||
      !result.class ||
      !result.telugu ||
      !result.hindi ||
      !result.english ||
      !result.maths ||
      !result.science ||
      !result.social
    ) {
      alert("⚠️ Please fill in all fields!");
      return;
    }

    try {
      const res = await fetch("http://localhost:8009/api/addresult", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(result),
      });

      if (res.ok) {
        alert("✅ Result added successfully!");
        setResult({
          exam: "",
          roll: "",
          class: 0,
          telugu: 0,
          hindi: 0,
          english: 0,
          maths: 0,
          science:0,
          social: 0,
        });
      } else {
        alert("❌ Failed to add result. Try again!");
      }
    } catch (err) {
      console.error("Error:", err);
      alert("⚠️ Backend not connected or error occurred!");
    }
  };

  return (
    <>
      <Teachernav />
      <div className={Style1.main}>
        <div className={Style1.heading}>Enter Result</div>

        <div className={Style1.inputs}>
          {/* Exam Type */}
          <div className={Style1.input1}>
            <label className={Style1.label}>Enter the Exam<br /></label>
            <select
              id="exam"
              name="exam"
              className={Style1.select}
              value={result.examType}
              onChange={handleChange}
            >
              <option value="">-- Select an exam --</option>
              <option value="midterm">Midterm Exam</option>
              <option value="final">Final Exam</option>
              <option value="quiz">Quiz</option>
              <option value="practical">Practical Exam</option>
            </select>
          </div>

          {/* Roll Number */}
          <div className={Style1.input1}>
            <label>Enter the roll number<br /></label>
            <input
              type="text"
              name="roll"
              value={result.roll}
              onChange={handleChange}
            />
          </div>

          {/* Class */}
          <div className={Style1.input1}>
            <label>Enter the class</label><br />
            <select
              name="class"
              value={result.class}
              onChange={handleChange}
            >
              <option value="class">-- Select a Class --</option>
              <option value="10">10</option>
              <option value="9">9</option>
              <option value="8">8</option>
              <option value="7">7</option>
            </select>
          </div>

          {/* Subject Marks */}
          <div className={Style1.subject}>Subject Marks</div>

          {[
            "telugu",
            "hindi",
            "english",
            "maths",
            "science",
            "social",
          ].map((sub) => (
            <div className={Style1.input1} key={sub}>
              <label>{sub.charAt(0).toUpperCase() + sub.slice(1)}<br /></label>
              <input
                type="number"
                name={sub}
                placeholder="enter marks"
                value={result[sub]}
                onChange={handleChange}
              />
            </div>
          ))}
        </div>

        <div className={Style1.save}>
          <button onClick={handleSubmit}>SaveResults</button>
        </div>
      </div>
    </>
  );
}



export default Addresult;
